export const getCamerasProducts = (): Product[] => CAMERAS_PRODUCTS;

export const getFeaturedCamerasProducts = (): Product[] => 
  CAMERAS_PRODUCTS.filter(product => product.featured);

export const getCamerasProductsByBadge = (badge: string): Product[] =>
  CAMERAS_PRODUCTS.filter(product => product.badge === badge);

export const getCamerasProductsByPriceRange = (min: number, max: number): Product[] =>
  CAMERAS_PRODUCTS.filter(product => product.price >= min && product.price <= max);
